SourceCode.Declaration:
/// <summary>
/// Seeded lifecycle reason codes per action (Clear France API v4.1 - 6.9-6.11). Reason codes are
/// a contract with the tax authority, not user data: the list form is read-only and the seeding
/// tops up missing codes rather than checking for emptiness, so a partial list repairs itself.
/// Global (not per-company) - the contract does not vary by legal entity.
/// </summary>
public class CELTLifecycleReasonCode extends common
{
}

Method.Source:
/// <summary>
/// Whether a reason code exists for an action.
/// </summary>
/// <param name = "_action">lifecycle action</param>
/// <param name = "_reasonCode">reason code</param>
/// <returns>true when present</returns>
public static boolean exist(CELTLifecycleAction _action, str _reasonCode)
{
    return (select firstonly RecId from CELTLifecycleReasonCode
        where CELTLifecycleReasonCode.Action     == _action
           && CELTLifecycleReasonCode.ReasonCode == _reasonCode).RecId != 0;
}
